p = 'explorations/coordinator/climb-batch-workflow.js'
s = open(p, encoding='utf-8').read()
start = s.index('// ---------------------------------------------------------------------------\n// The record lookup: the first step')
end = s.index('// ---------------------------------------------------------------------------\n// The shared prefix. batched')
new = r"""// ---------------------------------------------------------------------------
// The briefing: the first step of every role that works on a rung. The agents
// of the early climbs decided locally, and what they missed was on record: a
// ledger row, a POSITIONS entry, an earlier judge's ruling, the library's own
// precedent (explorations/reviews/worker-global-decisions.md). So the planner
// writes each rung's briefing from the record, a list of facts-extract.sh keys
// in its manifest entry: the rung worker reads it whole as its step 1, and the
// skeptic, the repair round and the judges read its checks sub-list, the
// decisions and ledger rows their checks need. Nothing is printed to every
// agent alike: a blanket read first cost more than it saved, and paid only
// through better decisions of rung workers (worker-context-cost.md). The tool
// prints in parts of at most 28 KB, under what one shell command shows an
// agent, and says the size. climb-batch-workflow.md, "Shared prefix".
// ---------------------------------------------------------------------------

const LOOKUP_TOOL = 'explorations/coordinator/tools/facts-extract.sh'
const keyOk = (q) => typeof q === 'string' && q.trim() !== '' && !q.startsWith('-') && !/["\x60$\\\n]/.test(q)
RUNGS.forEach(r => {
  for (const field of ['briefing', 'checks']) {
    if (r[field] === undefined) continue
    const bad = Array.isArray(r[field]) ? r[field].filter(q => !keyOk(q)) : [String(r[field])]
    if (bad.length) throw new Error('rung ' + r.id + ': ' + field + ' is a list of strings, none empty or opening with -, and none holding a double quote, a backtick, a dollar sign, a backslash or a newline, since each is rendered in double quotes: ' + bad.join(' | '))
  }
  const stray = (Array.isArray(r.checks) ? r.checks : []).filter(q => !(Array.isArray(r.briefing) && r.briefing.includes(q)))
  if (stray.length) throw new Error('rung ' + r.id + ': checks is a sub-list of briefing, and these keys are not in the briefing: ' + stray.join(' | '))
})
const keysOf = (r, field) => Array.isArray(r[field]) ? r[field] : []
// The command as the prompt shows it, one key a line, indented as code.
const lookupCommand = (keys) => ['        ' + LOOKUP_TOOL + ' \\'].concat(keys.map((q, i) => '            "' + q + '"' + (i < keys.length - 1 ? ' \\' : '')))
const SEARCH_FIRST = 'explorations/coordinator/INDEX.md, FACTS.md and POSITIONS.md beside it, the gap ledger (explorations/fortress-gap-ledger.md) and the maps under explorations/coordinator/map/'
const MORE_PARTS = 'Output that ends by naming a next part is continued by the same command with --part 2, then 3, until it says it printed the last.'

// Step 1 of the rung worker, and of a worker resumed after a stop: the rung's
// whole briefing.
function briefingStep(rung, where) {
  const keys = keysOf(rung, 'briefing')
  if (!keys.length) return ['1. This rung has no briefing. Before anything else, search ' + SEARCH_FIRST + ' for its topics, before the tree.']
  return [
'1. Before anything else, run this command in ' + where + ' and read all it prints. It is this rung\'s briefing, which the batch\'s planner wrote from the record for this rung: the decisions of Pavol\'s it rests on (POSITIONS.md), the gap-ledger rows it touches, earlier judges\' rulings, and the FACTS.md entries and map rows and sections of its area, each whole. ' + MORE_PARTS,
'',
...lookupCommand(keys),
'',
'   For a topic the briefing does not cover, search ' + SEARCH_FIRST + ' before the tree.',
  ]
}

// Step 1 of a skeptic, a repair round and a judge, on one rung (rungs = [rung],
// in its worktree) or on the merged tree (rungs = RUNGS, in the main tree): the
// checks slice of each rung's briefing. lead opens the step: step 1 of a
// numbered order by default, the words given in a role that has none.
function sliceStep(rungs, where, lead) {
  const sliced = rungs.filter(r => keysOf(r, 'checks').length)
  const one = rungs.length === 1
  const open = lead || '1. Before anything else,'
  if (!sliced.length) return [open + ' search ' + SEARCH_FIRST + ' for the decisions and ledger rows ' + (one ? 'this rung rests on' : 'the rungs rest on') + ', before the tree: ' + (one ? 'this rung\'s briefing has no checks list.' : 'no rung of this run has a checks list in its briefing.')]
  return [
open + ' run ' + (sliced.length > 1 ? 'these commands' : 'this command') + ' in ' + where + ' and read all ' + (sliced.length > 1 ? 'they print' : 'it prints') + '. ' + (one
  ? 'It is the part of this rung\'s briefing that the checks on it need: the decisions of Pavol\'s and the ledger rows the rung rests on, and the rulings and facts they turn on, each whole. The rung\'s first pass read the whole briefing.'
  : 'Each is the part of a rung\'s briefing that the checks on it need, for ' + sliced.map(r => r.id).join(', ') + ' in that order: the decisions of Pavol\'s and the ledger rows each rung rests on, and the rulings and facts they turn on, each whole.') + ' ' + MORE_PARTS,
'',
...[].concat.apply([], sliced.map((r, i) => (i ? [''] : []).concat(one ? [] : ['        # ' + r.id]).concat(lookupCommand(keysOf(r, 'checks'))))),
'',
'   For an entry ' + (one ? 'the slice lacks' : 'the slices lack') + ', search ' + SEARCH_FIRST + ' before the tree.',
  ]
}

"""
s = s[:start] + new + s[end:]

old_prefix_start = s.index("'## The record on file - read it before you search the tree',")
old_prefix_end = s.index("'## The territory map - read the parts your task needs, do not go looking',")
new_prefix = r"""'## Your briefing - read it before you search the tree',
'',
'The agents of the early climbs went wrong on decisions made locally, and what they missed was on record: a decision of Pavol\'s in explorations/coordinator/POSITIONS.md, a row of the gap ledger (explorations/fortress-gap-ledger.md), an earlier judge\'s ruling, the library\'s own way for the same family. So the batch\'s planner wrote a briefing for each rung from the record: the POSITIONS.md entries, the ledger rows and the earlier rulings the rung rests on, and the explorations/coordinator/FACTS.md entries (what the project has established, grouped by area, each cited by its bold title) and the map rows and sections of its area, each printed whole by ' + LOOKUP_TOOL + '. Step 1 of every role that works on a rung runs it: the rung worker reads the whole briefing, and the skeptic, the repair round and the judges read the part of it that their checks need. For a topic it does not cover, search explorations/coordinator/INDEX.md (one line per standalone note), FACTS.md, POSITIONS.md, the ledger and the relevant map below before the tree. Cite a FACTS entry by its bold title.',
'',
"""
s = s[:old_prefix_start] + new_prefix + s[old_prefix_end:]

# the role step 1s
s = s.replace("""function rungRole(rung) {""", """function rungRole(rung, repairRound) {""", 1)
s = s.replace("""...lookupStep([rung], 'your worktree (' + rung.path + ')'),""",
              """...(repairRound ? sliceStep([rung], 'your worktree (' + rung.path + ')') : briefingStep(rung, 'your worktree (' + rung.path + ')')),""", 1)
s = s.replace("""...lookupStep([rung], 'the rung\\'s worktree (' + rung.path + ')'),""",
              """...sliceStep([rung], 'the rung\\'s worktree (' + rung.path + ')'),""", 1)
s = s.replace("""  ? lookupStep([rung], 'the rung\\'s worktree (' + rung.path + ')').join('\\n')""",
              """  ? sliceStep([rung], 'the rung\\'s worktree (' + rung.path + ')').join('\\n')""", 1)
s = s.replace("""  : lookupStep(RUNGS, 'the main tree (' + MAIN + ')').join('\\n')""",
              """  : sliceStep(RUNGS, 'the main tree (' + MAIN + ')').join('\\n')""", 1)
s = s.replace("""...lookupStep(RUNGS, 'the main tree (' + MAIN + ')', 'First, before the ruling below,'),""",
              """...sliceStep(RUNGS, 'the main tree (' + MAIN + ')', 'First, before the ruling below,'),""", 1)
s = s.replace("""'First, before anything below: run the commands of step 1 of the order of work above, in ' + rung.path + ', and read all they print.',""",
              """'First, before anything below: take step 1 of the order of work above, in ' + rung.path + (verdict ? '. In a repair round it is the part of the briefing that the checks on the rung read, not the whole briefing, which the first pass read.' : ', the rung\\'s whole briefing.'),""", 1)
s = s.replace("""const repaired = await callAgent(PREFIX + rungRole(rung) + rung.tail + repairPrompt(rung, verdict, decision), {""",
              """const repaired = await callAgent(PREFIX + rungRole(rung, true) + rung.tail + repairPrompt(rung, verdict, decision), {""", 1)
open(p, 'w', encoding='utf-8').write(s)
PYEOF
grep -n "lookupStep\|hasList\|\.facts\|--common" explorations/coordinator/climb-batch-workflow.js; grep -n "sliceStep\|briefingStep\|rungRole(rung" explorations/coordinator/climb-batch-workflow.js | cut -c1-150

