  if (role === 'judge') return { kind: 'k', decision: 'repair', instructions: ['1'], ruling: 'r', summary: 's', forPavol: ['a judge point on ' + (rung || 'merged')] }
  if (role === 'gather') return { commits: [], conflicts: [], unresolved: false, summary: 's', pavolItems: globalThis.__route || [] }
  if (role === 'review' || role === 'review2') return { approved: true, blocking: [], fixed: [], stopsMet: [], summary: 's', forPavol: [], pavolItems: [] }
  if (role === 'gate' || role === 'gate2') return { green: true, failing: [], stopped: false, summary: 's' }
